START TRANSACTION READ ONLY;
SELECT JSON_OBJECT('table','context','data',CAST(data_json AS JSON)) FROM voice_runtime_context WHERE algorithm_run_id IN ('1790075460800','1790075649788');
SELECT JSON_OBJECT('table','proposal','data',CAST(data_json AS JSON)) FROM voice_proposal WHERE runtime_ref IN (SELECT id FROM voice_runtime_context WHERE algorithm_run_id IN ('1790075460800','1790075649788'));
SELECT JSON_OBJECT('table','execution','data',CAST(data_json AS JSON)) FROM voice_execution WHERE runtime_ref IN (SELECT id FROM voice_runtime_context WHERE algorithm_run_id IN ('1790075460800','1790075649788'));
SELECT JSON_OBJECT('table','event','receivedAt',received_at,'data',CAST(data_json AS JSON)) FROM voice_command_event WHERE execution_id IN (SELECT id FROM voice_execution WHERE runtime_ref IN (SELECT id FROM voice_runtime_context WHERE algorithm_run_id IN ('1790075460800','1790075649788'))) ORDER BY received_at;
SELECT JSON_OBJECT('table','audit','kind',kind,'detail',detail,'createdAt',created_at,'runtimeRef',runtime_ref) FROM voice_audit WHERE runtime_ref IN (SELECT id FROM voice_runtime_context WHERE algorithm_run_id IN ('1790075460800','1790075649788'));
SELECT JSON_OBJECT('table','outbox','executionId',execution_id,'status',status,'claimedAt',claimed_at) FROM voice_outbox WHERE execution_id IN (SELECT id FROM voice_execution WHERE runtime_ref IN (SELECT id FROM voice_runtime_context WHERE algorithm_run_id IN ('1790075460800','1790075649788')));
SELECT JSON_OBJECT('table','idempotency','userId',user_id,'operationKey',operation_key,'idempotencyKey',idempotency_key,'resourceId',resource_id,'bodyHash',body_hash) FROM voice_idempotency WHERE resource_id IN (SELECT id FROM voice_execution WHERE runtime_ref IN (SELECT id FROM voice_runtime_context WHERE algorithm_run_id IN ('1790075460800','1790075649788'))) OR resource_id IN (SELECT id FROM voice_proposal WHERE runtime_ref IN (SELECT id FROM voice_runtime_context WHERE algorithm_run_id IN ('1790075460800','1790075649788')));
COMMIT;